const KEY='syd-demo-v2';let db=JSON.parse(localStorage.getItem(KEY)||'null')||{employees:[{id:'SY001',name:'演示员工甲',dept:'综合管理部',job:'行政专员',level:'主管级',phone:'13800000001',edu:'本科',date:'2024-03-01',status:'待核查'},{id:'SY002',name:'演示员工乙',dept:'数据业务部',job:'产品经理',level:'员工级',phone:'13800000002',edu:'硕士',date:'2023-06-12',status:'已确认'},{id:'SY003',name:'演示员工丙',dept:'技术研发部',job:'开发工程师',level:'员工级',phone:'13800000003',edu:'本科',date:'2025-01-08',status:'待核查'}],tasks:[],changes:[],logs:[]};let rows=db.employees,pending=null,task=false,page='home';const app=document.getElementById('app'),fields={name:'姓名',dept:'部门',job:'职务',level:'职级',phone:'手机号',edu:'最高学历',date:'入职日期'};function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function save(action){if(action)db.logs.unshift({time:new Date().toLocaleString(),action});localStorage.setItem(KEY,JSON.stringify(db))}function toast(t){let x=document.createElement('div');x.className='toast';x.textContent=t;document.body.append(x);setTimeout(()=>x.remove(),3000)}function modal(title,body){document.getElementById('modal')?.remove();let d=document.createElement('div');d.id='modal';d.innerHTML=`<div class="shade"><div class="dialog"><button style="float:right" onclick="closeModal()">关闭 ×</button><h2>${title}</h2>${body}</div></div>`;document.body.append(d)}function closeModal(){document.getElementById('modal')?.remove()}function head(t,d){return `<header><div><h1>${t}</h1><small>${d}</small></div><span class="tag">内部演示 · 虚构数据</span></header>`}function table(rs){return `<table><tr><th>员工 / 工号</th><th>部门 / 职务</th><th>学历</th><th>核查状态</th><th>操作</th></tr>${rs.map(r=>`<tr><td><b>${esc(r.name)}</b><br><small>${r.id}</small></td><td>${esc(r.dept)}<br><small>${esc(r.job)}</small></td><td>${esc(r.edu)}</td><td><span class="tag">${r.status}</span></td><td><button onclick="detail('${r.id}')">档案详情</button></td></tr>`).join('')}</table>${rs.length?'':'<p>没有符合条件的员工</p>'}`}function view(p){page=p;let done=rows.filter(r=>r.status==='已确认').length,wait=db.changes.filter(c=>c.status==='待审核');app.innerHTML=head(({home:'人事数据工作台',list:'员工台账',tasks:'核查任务',self:'我的信息核查',review:'变更审核',export:'导出中心',logs:'操作记录'})[p],'档案预填 → 员工核查 → 变更审核 → 统一复用')+(p==='home'?`<div class="cards">${[['员工总数',rows.length],['已完成核查',done],['待审核申请',wait.length],['核查完成率',Math.round(done/rows.length*100)+'%']].map(([t,n])=>`<div class="card">${t}<strong>${n}</strong></div>`).join('')}</div><section><h2>本期人员信息核查</h2><p>统一掌握人员数据，减少重复填报。先由管理员确认任务范围，再由员工核查本人资料。</p><button onclick="view('tasks')">管理核查任务</button><button onclick="view('self')">进入员工视角 →</button><div class="note">建议演示路径：创建任务 → 甲员工修改电话 → 管理员审核 → 导出正式台账。浏览器本地保存演示操作。</div>${table(rows)}</section>`:p==='list'?`<section class="space"><button onclick="editEmployee()">＋ 新增演示员工</button><input id="q" placeholder="搜索姓名 / 工号" oninput="filter()"><select id="dep" onchange="filter()"><option value="">全部部门</option>${[...new Set(rows.map(r=>r.dept))].map(d=>`<option>${esc(d)}</option>`).join('')}</select><select id="state" onchange="filter()"><option value="">全部状态</option><option>待核查</option><option>待审核</option><option>待补充</option><option>已确认</option></select><div id="tbl">${table(rows)}</div></section>`:p==='tasks'?`<section class="space"><button onclick="taskForm()">＋ 创建核查任务</button><table><tr><th>任务名称</th><th>截止日期</th><th>范围</th><th>进度</th><th>操作</th></tr>${db.tasks.map((t,i)=>`<tr><td>${esc(t.name)}<br><small>${t.closed?'已结束':'进行中'}</small></td><td>${t.date}</td><td>${t.ids.length} 人</td><td>${t.ids.filter(id=>rows.find(r=>r.id===id)?.status==='已确认').length}/${t.ids.length}</td><td><button onclick="taskDetail(${i})">查看进度</button>${t.closed?'':`<button onclick="db.tasks[${i}].closed=true;save('结束核查任务');view('tasks')">结束任务</button>`}</td></tr>`).join('')}</table>${db.tasks.length?'':'<div class="note">暂无任务。创建任务后可查看成员核查进度。</div>'}</section>`:p==='self'?`<div class="note">员工演示身份：${rows[0].name}｜仅核查本人信息。需先逐项勾选，再确认或申请修改。</div><section><h2>我的基本档案 <span class="tag">${rows[0].status}</span></h2><form id="selfForm">${Object.entries(fields).map(([k,t])=>`<label class="field"><span>${t}</span><input name="${k}" value="${esc(rows[0][k])}" type="${k==='date'?'date':'text'}" required><input type="checkbox" class="check" aria-label="核对${t}"> 已核对</label>`).join('')}<label>修改说明<input name="reason" placeholder="存在变更时必填"></label><button type="button" onclick="submitSelf()">确认并提交</button><button type="button" onclick="document.querySelectorAll('.check').forEach(x=>x.checked=true)">全部标记已核对</button></form><h3>申请历史</h3>${db.changes.filter(c=>c.id===rows[0].id).map(c=>`<p><span class="tag">${c.status}</span> ${esc(c.time)} ${esc(c.feedback||'')}</p>`).join('')||'<p class="muted">暂无申请记录</p>'}</section>`:p==='review'?`<section class="space"><h2>变更申请</h2>${db.changes.map((c,i)=>`<div class="note"><b>${esc(rows.find(r=>r.id===c.id)?.name)}</b> · ${esc(c.time)} <span class="tag">${c.status}</span><p>${Object.keys(c.values).map(k=>fields[k]).join('、')}</p><button onclick="reviewDetail(${i})">查看差异 / 审核</button></div>`).join('')||'<p>暂无变更申请，请在员工核查中修改一项资料。</p>'}</section>`:p==='export'?`<section class="space"><h2>生成正式台账</h2><div class="note">仅导出当前正式档案，待审核修改不会被导出。已收到 OA V1.2 模板；此处为通用台账 CSV，OA 分册映射见下方。集团人资模板仍待确认。</div><label>范围<select id="expstate"><option value="all">全部员工</option><option value="done">仅已确认员工</option></select></label><h3>选择导出字段</h3><div class="export-fields">${Object.entries(fields).map(([k,t])=>`<label class="export-option"><input class="expfield" value="${k}" type="checkbox" checked>${t}</label>`).join('')}</div><p><button onclick="download()">生成并下载 CSV</button></p></section>`:`<section class="space"><h2>本机演示操作记录</h2><p class="muted">仅演示业务留痕；正式系统须服务端防篡改存储。</p>${db.logs.map(l=>`<p><small>${esc(l.time)}</small>　${esc(l.action)}</p>`).join('')||'<p>暂无记录</p>'}<button onclick="modal('重置演示','<p>将清空此浏览器保存的全部演示操作。</p><button onclick=\"localStorage.removeItem(KEY);location.reload()\">确认重置</button>')">重置演示数据</button></section>`)}function filter(){let q=document.getElementById('q').value,d=document.getElementById('dep').value,s=document.getElementById('state').value;document.getElementById('tbl').innerHTML=table(rows.filter(r=>(r.name.includes(q)||r.id.includes(q))&&(!d||r.dept===d)&&(!s||r.status===s)))}function detail(id){let r=rows.find(r=>r.id===id);modal('员工档案',`<span class="tag">${r.status}</span><p>工号：${r.id}</p>${Object.entries(fields).map(([k,t])=>`<p>${t}：${esc(r[k])}</p>`).join('')}<hr><p>资料来源：演示台账｜纸质档案位置：待登记</p><p>照片规范、原始0—13项字段：待业务确认</p>`)}function editEmployee(){modal('新增演示员工',`<form id="newform"><label>工号<input name="id" required></label>${Object.entries(fields).map(([k,t])=>`<label>${t}<input name="${k}" type="${k==='date'?'date':'text'}" required></label>`).join('')}<button>保存档案</button></form>`);document.getElementById('newform').onsubmit=e=>{e.preventDefault();let r=Object.fromEntries(new FormData(e.target));if(rows.some(x=>x.id===r.id))return toast('工号重复');if(!/^1\d{10}$/.test(r.phone))return toast('手机号应为11位');rows.push({...r,status:'待核查'});save('新增员工 '+r.id);closeModal();view('list')}}function taskForm(){modal('创建核查任务',`<form id="taskform"><label>任务名称<input name="name" required placeholder="例如：年度员工信息核查"></label><label>截止日期<input name="date" type="date" required min="2026-10-26"></label><h3>选择核查人员</h3>${rows.map(r=>`<label><input type="checkbox" name="member" value="${r.id}" checked>${esc(r.name)} / ${esc(r.dept)}</label>`).join('')}<p class="muted">发布仅模拟任务生成，不发送真实通知。</p><button>确认发布</button></form>`);document.getElementById('taskform').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),ids=f.getAll('member');if(!ids.length)return toast('至少选择一人');db.tasks.push({name:f.get('name'),date:f.get('date'),ids,closed:false});save('发布核查任务 '+f.get('name'));closeModal();view('tasks')}}function taskDetail(i){let t=db.tasks[i];modal(esc(t.name),`<p>截止：${t.date}｜${t.closed?'已结束':'进行中'}</p>${table(rows.filter(r=>t.ids.includes(r.id)))}<button onclick="save('模拟催办任务');toast('模拟催办已记录，未发送真实消息')">模拟催办未完成人员</button>`)}function submitSelf(){if(db.changes.some(c=>c.id===rows[0].id&&c.status==='待审核'))return toast('已有待审核申请，请先完成审核');let f=document.getElementById('selfForm');if(!f.reportValidity())return;if([...f.querySelectorAll('.check')].some(x=>!x.checked))return toast('请逐项核对后勾选');let data=Object.fromEntries(new FormData(f)),values={},old={};if(!/^1\d{10}$/.test(data.phone))return toast('手机号应为11位');Object.keys(fields).forEach(k=>{if(data[k]!==rows[0][k]){values[k]=data[k];old[k]=rows[0][k]}});if(Object.keys(values).length){if(!data.reason.trim())return toast('请说明修改原因');db.changes.unshift({id:rows[0].id,values,old,reason:data.reason,status:'待审核',time:new Date().toLocaleString()});rows[0].status='待审核';save('员工提交变更申请')}else{rows[0].status='已确认';save('员工确认资料无误')}view('self');toast('提交成功')}function reviewDetail(i){let c=db.changes[i];modal('变更差异与审核',`<table><tr><th>字段</th><th>原值</th><th>申请值</th></tr>${Object.keys(c.values).map(k=>`<tr><td>${fields[k]}</td><td>${esc(c.old[k])}</td><td style="color:#246de3">${esc(c.values[k])}</td></tr>`).join('')}</table><p>申请说明：${esc(c.reason)}</p>${c.status==='待审核'?`<label>审核意见<input id="feedback" placeholder="退回时必填"></label><button onclick="decide(${i},true)">审核通过</button><button onclick="decide(${i},false)">退回补充</button>`:`<p>${c.status}：${esc(c.feedback||'无补充意见')}</p>`}`)}function decide(i,ok){let c=db.changes[i],feedback=document.getElementById('feedback').value.trim(),r=rows.find(r=>r.id===c.id);if(!ok&&!feedback)return toast('退回请填写理由');if(ok&&Object.keys(c.old).some(k=>r[k]!==c.old[k]))return toast('正式数据已变化，请复核');if(ok)Object.assign(r,c.values);r.status=ok?'已确认':'待补充';c.status=ok?'已通过':'已退回';c.feedback=feedback;save((ok?'审核通过 ':'退回申请 ')+c.id);closeModal();view('review');toast('处理完成')}function download(){let keys=[...document.querySelectorAll('.expfield:checked')].map(x=>x.value);if(!keys.length)return toast('至少选择一个字段');let rs=rows.filter(r=>document.getElementById('expstate').value==='all'||r.status==='已确认'),cell=x=>'"'+String(x??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"',csv='\ufeff'+[['工号',...keys.map(k=>fields[k]),'核查状态'],...rs.map(r=>[r.id,...keys.map(k=>r[k]),r.status])].map(a=>a.map(cell).join(',')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='正式员工台账_演示.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);save('导出正式台账 '+rs.length+' 人');toast('已生成 '+rs.length+' 人台账')}view('home');
const legacyView=view;let activeBook=0;db.books=db.books||{};db.bookChecks=db.bookChecks||{};const rules=['基本信息须更新出生日期、民族、籍贯、参加工作时间、政治面貌、入党时间及婚姻状况。','所属公司、部门、职务和职位须映射基础资料编码；职务与职位分别管理。','填报全部学历，按时间由早到晚排列，本科、硕士等经历均保留。','填报全部职称经历，包括初级、中级、高级。','填报全部职业技能证书；最高标志不得同时设置多条。','填报全部资格证书经历，核对获取时间与确认日期。','核实手机号、户口所在地、实际居住地址及电子邮件。','首条起始时间与参加工作时间一致；相邻经历时间衔接、不重叠；待业也作为经历。','按模板维护体重（kg）、身高（cm）。','兵役信息需完整，相关情况附佐证材料；不适用的必填条件待业务确认。','未婚：父母及亲兄弟姐妹；已婚：配偶、子女、父母、配偶父母及亲兄弟姐妹。退休人员按说明填写原单位或居住地。','奖惩信息完整填写并附佐证材料。','特殊信息仅限授权人员查看，填写应以真实情况为准。'];
view=function(p){if(p==='self'){renderBooks();return}legacyView(p);if(p==='home'){app.insertAdjacentHTML('beforeend',`<section class="space"><h2>OA V1.2 填报准备</h2><div class="cards"><div class="card">档案分册<strong>13</strong></div><div class="card">照片规范<strong>&lt;100KB</strong></div><div class="card">数据关联<strong>工号</strong></div></div><p>按原始表格逐册核对，保留全部学历、证书与任职经历。</p><button onclick="view('self')">进入十三册核查 →</button><button onclick="photoPanel()">照片检查</button></section>`)}if(p==='export')app.insertAdjacentHTML('beforeend',`<section class="space"><h2>OA 模板映射预览</h2><p>选择分册检查实际字段标识。当前下载为映射预览 JSON，不冒充可导入的 XLS 文件。</p><select id="mapbook">${SCHEMA.map((g,i)=>`<option value="${i}">${g.name}</option>`).join('')}</select><button onclick="exportBook()">下载字段映射与演示记录</button></section>`)};
function renderBooks(){page='self';let g=SCHEMA[activeBook],records=db.books[activeBook]||[];app.innerHTML=head('员工档案 · 十三册核查','OA 导入模板 V1.2 ｜ 演示员工甲 ｜ 与实际表格逐项对应')+`<div class="note">原表中的工号用作分册关联；系统主键、操作人和操作时间由正式系统生成。演示请勿输入真实个人信息。</div><div class="booklayout"><nav class="booknav">${SCHEMA.map((s,i)=>`<button class="${activeBook===i?'selected':''}" onclick="activeBook=${i};renderBooks()">${s.name}<small>${db.bookChecks[i]?' ✓ 已核对':(db.books[i]||[]).length+' 条记录'}</small></button>`).join('')}<button onclick="photoPanel()">0 员工照片</button></nav><section><h2>${g.name}</h2><div class="note">${rules[activeBook]}</div><p class="muted">标有 * 的字段来自原模板。模板中的代码应经正式字典转换，当前填写区保留原字段名称。</p><button onclick="bookForm()">＋ ${records.length?'新增一条记录':'补充本册资料'}</button><button onclick="db.bookChecks[activeBook]=!db.bookChecks[activeBook];save('切换分册核对状态');renderBooks()">${db.bookChecks[activeBook]?'取消核对':'标记本册已核对'}</button>${records.length?records.map((r,i)=>`<div class="record"><h3>记录 ${i+1}</h3><div class="recordgrid">${g.fields.map(f=>`<p><small>${esc(f.title)}</small><br>${esc(r[f.code]||'—')}</p>`).join('')}</div><button onclick="bookForm(${i})">编辑</button><button onclick="removeBook(${i})">删除</button></div>`).join(''):'<div class="empty">本册尚未维护资料<br><small>请按实际情况补充；无相关经历时，适用规则需由业务确认。</small></div>'}<hr><p>本地分册核对进度：${Object.values(db.bookChecks).filter(Boolean).length} / 13</p><button onclick="legacyView('self')">进入提交与审核演示 →</button><p class="muted">分册编辑暂存与原有基本信息审核为两个演示环节，尚未实现全册差异审核。</p></section></div>`}
function bookForm(index){let g=SCHEMA[activeBook],r=(db.books[activeBook]||[])[index]||{};modal(g.name+' · '+(index===undefined?'新增':'编辑'),`<form id="bookform">${g.fields.map((f,i)=>`<label>${esc(f.title)}<input name="f${i}" value="${esc(r[f.code]||'')}" ${f.required?'required':''} placeholder="${f.title.includes('时间')||f.title.includes('日期')?'YYYY-MM-DD':'按原模板填写'}"></label>`).join('')}<button>保存本册记录</button></form>`);document.getElementById('bookform').onsubmit=e=>{e.preventDefault();let fd=new FormData(e.target),r={};g.fields.forEach((f,i)=>r[f.code]=fd.get('f'+i));db.books[activeBook]=db.books[activeBook]||[];if(index===undefined)db.books[activeBook].push(r);else db.books[activeBook][index]=r;db.bookChecks[activeBook]=false;save('维护分册 '+g.name);closeModal();renderBooks();toast('已暂存，需重新核对')}}function removeBook(i){modal('删除记录',`<p>确认删除本册第 ${i+1} 条演示记录？</p><button onclick="db.books[activeBook].splice(${i},1);db.bookChecks[activeBook]=false;save('删除分册记录');closeModal();renderBooks()">确认删除</button>`)}function photoPanel(){modal('0 员工照片 · 规范检查',`<div class="note">蓝底、近期免冠、1寸或2寸、着装规范、非自拍。文件小于100KB，文件名使用员工工号。</div><p>当前演示工号：SY001</p><input type="file" accept="image/*" id="photo"><div id="photostate"></div><p class="muted">仅在本机预览，不上传。背景、免冠与着装由人工核对；原说明未指定像素及格式白名单。</p>`);document.getElementById('photo').onchange=e=>{let f=e.target.files[0];if(!f)return;let pass=f.size<100*1024&&f.name.replace(/\.[^.]+$/,'')==='SY001'&&f.type.startsWith('image/');document.getElementById('photostate').textContent=(pass?'文件基础检查通过':'检查未通过：请核对大小、工号命名及图片类型')+' · '+(f.size/1024).toFixed(1)+'KB';if(f.type.startsWith('image/')){let img=document.createElement('img');img.style='max-width:180px;display:block;margin-top:20px';img.src=URL.createObjectURL(f);img.onload=()=>URL.revokeObjectURL(img.src);document.getElementById('photostate').append(img)}}}function exportBook(){let i=+document.getElementById('mapbook').value,a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({template:SCHEMA[i],employeeCode:'SY001',records:db.books[i]||[]},null,2)],{type:'application/json'}));a.download=SCHEMA[i].name+'_映射预览.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);save('导出分册映射预览')}view('home');
/* V1 personnel lifecycle demonstration */
db.events=db.events||[];rows.forEach(r=>{r.employment=r.employment||'在职'});const priorView=view;
view=function(p){if(p==='people'){peoplePage();return}if(p==='operations'){operationsPage();return}priorView(p);if(p==='home'){app.querySelector('h1').textContent='人员信息管理工作台';app.insertAdjacentHTML('afterbegin','<div class="note"><b>长期维护的人员主档</b> · 入职建档 → 日常变更 → 定期核查 → 离职归档<br>OA 填报从正式档案取数，持续维护由综合管理部门负责。</div>');app.insertAdjacentHTML('beforeend',`<section class="space"><h2>人员运营待办</h2><p>在职 ${rows.filter(r=>r.employment==='在职').length} 人 · 离职归档 ${rows.filter(r=>r.employment==='离职归档').length} 人 · 人事事件待审核 ${db.events.filter(e=>e.status==='待审核').length} 项</p><button onclick="view('people')">处理人事事件</button><button onclick="view('operations')">运行维护与交接</button></section>`)} };
function peoplePage(){page='people';app.innerHTML=head('人员生命周期','人员状态与核查状态分别管理 · 调动保留历史 · 离职保留档案')+`<section class="space"><h2>人员与任职关系</h2><table><tr><th>员工</th><th>当前部门</th><th>职务</th><th>人员状态</th><th>操作</th></tr>${rows.map(r=>`<tr><td>${esc(r.name)}<br>${esc(r.id)}</td><td>${esc(r.dept)}</td><td>${esc(r.job)}</td><td>${r.employment}</td><td><button onclick="eventForm('${r.id}')">发起人事事件</button></td></tr>`).join('')}</table></section><section class="space"><h2>人事事件与任职历史</h2><p class="muted">当前演示即时生效事件；正式系统需支持审批权限和按日期生效。</p>${db.events.map((e,i)=>`<div class="record"><b>${esc(e.name)} · ${e.type}</b> <span class="tag">${e.status}</span><p>${esc(e.old.dept)} / ${esc(e.old.job)} / ${e.old.employment} → ${esc(e.next.dept)} / ${esc(e.next.job)} / ${e.next.employment}</p><p>申请说明：${esc(e.reason)}<br><small>${esc(e.time)}</small></p>${e.status==='待审核'?`<button onclick="eventReview(${i})">审核与处理</button>`:`<p>审核意见：${esc(e.feedback||'通过')}</p>`}</div>`).join('')||'<p>尚无人事事件。可发起调岗、离职归档或重新入职申请。</p>'}</section>`}
function eventForm(id){let r=rows.find(r=>r.id===id);modal('人事事件申请',`<form id="eventform"><p>${esc(r.name)} · ${id} · ${r.employment}</p><label>事件类型<select name="type"><option>调岗调部门</option><option>离职归档</option><option>重新入职</option></select></label><label>目标部门<input name="dept" value="${esc(r.dept)}" required></label><label>目标职务<input name="job" value="${esc(r.job)}" required></label><label>事件说明<input name="reason" required></label><p class="muted">保存为待审核，当前正式档案不会立即改变。</p><button>提交申请</button></form>`);document.getElementById('eventform').onsubmit=e=>{e.preventDefault();if(db.events.some(x=>x.id===id&&x.status==='待审核'))return toast('该员工已有待审核人事事件');let f=Object.fromEntries(new FormData(e.target));if(f.type==='重新入职'&&r.employment!=='离职归档')return toast('仅离职归档人员可重新入职');if(f.type!=='重新入职'&&r.employment!=='在职')return toast('该事件仅适用于在职人员');db.events.unshift({id,name:r.name,type:f.type,reason:f.reason,time:new Date().toLocaleString(),status:'待审核',old:{dept:r.dept,job:r.job,employment:r.employment},next:{dept:f.dept,job:f.job,employment:f.type==='离职归档'?'离职归档':'在职'}});save('提交人事事件 '+id);closeModal();peoplePage()}}
function eventReview(i){modal('人事事件审核',`<p>审核通过后更新当前人员关系，事件记录永久保留在本机演示历史。</p><label>审核意见<input id="eventfeedback" placeholder="退回时必填"></label><button onclick="decideEvent(${i},true)">通过并生效</button><button onclick="decideEvent(${i},false)">退回申请</button>`)}function decideEvent(i,ok){let e=db.events[i],r=rows.find(r=>r.id===e.id),f=document.getElementById('eventfeedback').value.trim();if(!ok&&!f)return toast('请填写退回意见');if(ok&&Object.keys(e.old).some(k=>r[k]!==e.old[k]))return toast('正式关系已变化，请重新发起');if(ok)Object.assign(r,e.next);e.status=ok?'已生效':'已退回';e.feedback=f;e.reviewTime=new Date().toLocaleString();save('人事事件'+e.status+' '+e.id);closeModal();peoplePage();toast('处理完成')}
function operationsPage(){page='operations';app.innerHTML=head('运行维护与交接','让资料可持续维护，让系统可交接')+`<section class="space"><h2>维护责任</h2><table><tr><th>责任角色</th><th>日常工作</th></tr><tr><td>综合管理部门</td><td>建档、组织字典、资料审核、质量检查、授权导出</td></tr><tr><td>员工本人</td><td>申报变化、补充经历、定期核查</td></tr><tr><td>信息技术运维</td><td>账号集成、服务运行、备份恢复、发布与交接</td></tr></table></section><section class="space"><h2>本机演示快照</h2><p>可下载当前虚构数据用于评审留存。该文件不等于生产数据库备份，请勿用于真实人员数据。</p><button onclick="snapshot()">下载演示快照 JSON</button><p>正式数据库、附件存储、定时备份、告警和恢复演练：待正式建设。</p></section><section class="space"><h2>正式交付检查项</h2><p>源码与部署说明、数据库迁移脚本、接口文档、配置字典、业务手册、运维手册、账号和资产归属、备份恢复演练、发布回退方案。</p><p class="muted">本页展示建设要求，不代表已配置生产监控或备份。</p></section>`}function snapshot(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.download='人员平台_虚构数据快照.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);save('下载演示快照')}
view('home');
